import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Prompt 模板库","description":"","frontmatter":{},"headers":[],"relativePath":"prompts/index.md","filePath":"prompts/index.md","lastUpdated":1785729506000}'),d={name:"prompts/index.md"};function s(p,t,l,n,i,h){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="prompt-模板库" tabindex="-1">Prompt 模板库 <a class="header-anchor" href="#prompt-模板库" aria-label="Permalink to &quot;Prompt 模板库&quot;">​</a></h1><p>这个板块的东西是拿来<strong>抄</strong>的，不是拿来读的。</p><h2 id="统一格式" tabindex="-1">统一格式 <a class="header-anchor" href="#统一格式" aria-label="Permalink to &quot;统一格式&quot;">​</a></h2><p>每条 Prompt 都按四段呈现：</p><table tabindex="0"><thead><tr><th>段落</th><th>内容</th></tr></thead><tbody><tr><td><strong>适用场景</strong></td><td>什么情况下用这条，什么情况下别用</td></tr><tr><td><strong>可复制 Prompt</strong></td><td>代码块，直接复制，方括号 <code>[]</code> 处替换成你的内容</td></tr><tr><td><strong>参数说明</strong></td><td>每个关键词在控制什么，想调整效果该动哪一处</td></tr><tr><td><strong>常见翻车点</strong></td><td>已知会出问题的地方，以及绕过去的办法</td></tr></tbody></table><h2 id="本板块内容" tabindex="-1">本板块内容 <a class="header-anchor" href="#本板块内容" aria-label="Permalink to &quot;本板块内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>用于</th></tr></thead><tbody><tr><td><a href="/prompts/structure">Prompt 结构通法</a></td><td>**先读这篇。**所有 Prompt 的底层结构，读完能自己写</td></tr><tr><td><a href="/prompts/product-still">产品静物 / 电商主图</a></td><td>主图、KV、海报、详情页素材</td></tr><tr><td><a href="/prompts/video-storyboard">短视频分镜脚本</a></td><td>把分镜表翻译成视频生成 Prompt</td></tr><tr><td><a href="/prompts/copywriting">广告文案与口播</a></td><td>slogan、口播稿、字幕、卖点提炼</td></tr></tbody></table><h2 id="一条重要提醒" tabindex="-1">一条重要提醒 <a class="header-anchor" href="#一条重要提醒" aria-label="Permalink to &quot;一条重要提醒&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">别把 Prompt 当咒语</p><p>同一条 Prompt 在不同模型、不同版本上的表现差异很大。这里给的是<strong>结构和思路</strong>，不是保证出片的魔法字符串。</p><p>正确的用法：理解每一段在控制什么，然后按你的需求改写。照抄不改，效果通常一般——因为它没写你的产品。</p></div><h2 id="待补充" tabindex="-1">待补充 <a class="header-anchor" href="#待补充" aria-label="Permalink to &quot;待补充&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">有意留白</p><ul><li><a href="/prompts/spokesperson">人物代言</a></li><li><a href="/prompts/ugc-style">UGC 仿真风</a></li></ul></div><p>想加自己的 Prompt？用 <a href="/templates/prompt-card">Prompt 卡片模板</a>。</p>',12)])])}const b=r(d,[["render",s]]);export{c as __pageData,b as default};
